renderNode.$fn:
({ node, expanded, hasChildren, selected, elementProps }) => (
      <Box
        {...elementProps}
        flexDirection="row"
        alignItems="center"
        gap="$xs"
        paddingVertical="$xs"
        paddingHorizontal="$xs"
        borderRadius="$xs"
        backgroundColor={selected ? "$color4" : "transparent"}
        hoverStyle={{ backgroundColor: "$color3" }}
      >
        <Text width="$xxs" textAlign="center" fontSize="$xs">
          {hasChildren ? (expanded ? "▼" : "▶") : "·"}
        </Text>
        <Text fontSize="$xs">{hasChildren ? "📁" : "📄"}</Text>
        <Text
          fontSize="$sm"
          color={selected ? "$color11" : "$color"}
          fontWeight={selected ? "600" : "400"}
        >
          {node.label}
        </Text>
      </Box>
    )

valueComponent.$fn:
({ value }: { value: FileInputValue }) => {
      if (!value) return null;
      const files = Array.isArray(value) ? value : [value];
      return (
        <Box flexDirection="row" gap="$xs" alignItems="center">
          <Text>📄</Text>
          <Text>{files.map((f) => f.name).join(", ")}</Text>
          <Text opacity={0.5}>
            ({files.length} file{files.length !== 1 ? "s" : ""})
          </Text>
        </Box>
      );
    }

